/* 第02轮生效漫画界面；后加载，只接管漫画章节，视频与待解析导入不改。 */
(()=>{
  const C=Cimora,{S,M,E,path,link}=C,Q=M.comic;
  const B=(text,action,id='',extra='',cls='cm-button ghost')=>`<button type="button" class="${cls}" data-comic="${action}" data-id="${E(id)}" ${extra}>${text}</button>`;
  const safe=c=>{const error=Q.blocked(c);if(error)S.toast(error);return !error;},paint=()=>S.render();
  const artURL=image=>image?.image||'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(Art.svg(image?.art||0).replace(/<text\b[^>]*>[\s\S]*?<\/text>/g,''));
  const imageHTML=(image,alt='无字示意底图')=>`<img src="${E(artURL(image))}" alt="${E(alt)}">`;
  const textHTML=b=>{const t=b.comic.text;return `<div class="co-text-layer">${t.narration?`<p class="co-narration">${E(t.narration)}</p>`:''}${b.dialogue?`<p class="co-speech"><b>${E(t.speakerName||'未指定')}：</b>${E(b.dialogue)}</p>`:''}${t.sfx?`<p class="co-sfx">${E(t.sfx)}</p>`:''}</div>`;};
  const adoptedLabel=b=>{const a=Q.adopted(b);return a?'已采用图像 v'+a.version:'尚未采用图像 · 旧示意预览'};
  const refs=b=>[...b.comic.cast.map(r=>r.snapshot.name+' v'+r.version),...(b.comic.scene?[b.comic.scene.snapshot.name+' v'+b.comic.scene.version]:[])].join(' / ')||'尚未引用角色/场景，可先编辑脚本';
  const imageChanged=b=>Q.adopted(b)&&JSON.stringify(Q.adopted(b).input)!==JSON.stringify(Q.imageInput(b));
  function hint(c){return `<div class="cm-notice">无字底图和文字层独立保存 · 图像为原创矢量示意，生成是本机模拟，不读取收费模型。</div><div class="co-toolbar">${B('角色与场景草案','assets')}${B('建立并联动占位草案','seed')}${link('长条排版与阅读 →',path(c,'comic','flow'),'cm-button primary')}</div>`;}
  const oldBoards=C.adaptationBoards;
  C.adaptationBoards=c=>{if(c.c.kind==='episode'||c.e.importDraft)return oldBoards(c);Q.ensure(c);const range=M.adaptation.range(c);return `${hint(c)}<div class="cm-stage-toolbar"><div><h2>逐格写清楚，再选择画面。</h2><p>原文${range.total}句 · 已整理前${range.done}句 · 剩余${range.remaining}句。${range.remaining?'下一批第'+range.nextStart+'–'+range.nextEnd+'句。':''}</p></div><div>${range.remaining?'<button class="cm-button ghost" data-adapt="draft">继续整理剩余 '+range.remaining+' 句</button>':''}${B('＋ 添加分格','add')}${B('批量生成未采用格示例','batch')}</div></div><div class="co-panel-list">${c.e.boards.map((b,i)=>`<article class="cm-panel co-panel cm-board" id="co-panel-${b.id}"><div class="co-preview"><span class="co-index">第${i+1}格 · ${adoptedLabel(b)}</span>${imageHTML(Q.adopted(b)||{art:b.art},b.title+' · 无字底图')}${textHTML(b)}</div><div class="co-panel-info"><h3>${E(b.title)}</h3><small>分格 v${b.version} · ${E(b.shot)} · ${b.comic.images.length} 图像候选</small><p>${E(b.action)}</p><p class="cm-help">${E(refs(b))}${b.comic.outfit?' / 本格服装：'+E(b.comic.outfit):''}</p>${imageChanged(b)?'<div class="cm-notice">画面输入已变化，旧采用底图保留；可单格重做并比较。</div>':''}<div class="co-toolbar">${B('编辑脚本与文字层','edit',b.id)}${B('生成 / 重做本格示例','generate',b.id)}${B('比较图像候选（'+b.comic.images.length+'）','compare',b.id)}</div><div class="co-toolbar">${B('↑','move',b.id,`data-dir="-1" aria-label="上移第${i+1}格" ${i===0?'disabled':''}`)}${B('↓','move',b.id,`data-dir="1" aria-label="下移第${i+1}格" ${i===c.e.boards.length-1?'disabled':''}`)}${B('复制分格','duplicate',b.id)}${(c.p.episodes||[]).flatMap(ep=>M.production.shots(M.ensure(c.p,ep)).filter(s=>s.sources.some(r=>r.chapterId===c.c.id&&r.panelId===b.id)).map(s=>link('定位改编镜头 ↗',path({p:c.p,c:ep},'boards','flow')+'&shot='+s.id,'cm-text-link'))).join('')}</div><details><summary>采用图像与来源追溯</summary>${provenance(b)}</details></div></article>`).join('')}</div>`;};
  function provenance(b){const a=Q.adopted(b);return `<p>无字底图：${a?E(a.id)+' / v'+a.version:'尚未采用，当前只显示旧示意'}</p><p>对白归属：${E(b.comic.text.speakerName||'未指定')} · 文字独立于图像</p><p>当前脚本引用：${E(refs(b))}</p>${a?`<p>图像生成时引用：${E([...a.input.cast.map(r=>r.snapshot.name+' v'+r.version),a.input.scene?rName(a.input.scene):'无场景'].join(' / '))}</p>`:''}`;}
  const rName=r=>r.snapshot.name+' v'+r.version;
  function edit(c,b){const q=b.comic;S.modal('编辑第'+(c.e.boards.indexOf(b)+1)+'格 · 脚本与独立文字层',`<form data-comic-form="panel" data-id="${b.id}"><div class="co-edit-grid"><section><label class="cm-label">分格标题<input name="title" required maxlength="100" value="${E(b.title)}"></label><label class="cm-label">画面动作<textarea name="action" rows="3" required>${E(b.action)}</textarea></label><label class="cm-label">景别<select name="shot">${[...new Set(['远景','中景','人物特写','道具特写','双人中景',b.shot])].map(t=>`<option ${t===b.shot?'selected':''}>${E(t)}</option>`).join('')}</select></label><fieldset><legend>出场角色 · 已引用版本保留</legend>${Q.assets(c,'角色').map(a=>`<label class="cm-check"><input type="checkbox" name="cast" value="${a.id}" ${q.cast.some(r=>r.id===a.id)?'checked':''}>${E(a.name)} · 当前v${a.version}${q.cast.find(r=>r.id===a.id)?' / 原引用v'+q.cast.find(r=>r.id===a.id).version:''}</label>`).join('')||'<p>可先不选；到角色与场景草案建立占位角色。</p>'}</fieldset><label class="cm-label">场景 · 已引用版本保留<select name="sceneId"><option value="">暂不指定</option>${Q.assets(c,'场景').map(a=>`<option value="${a.id}" ${q.scene?.id===a.id?'selected':''}>${E(a.name)} · 当前v${a.version}</option>`).join('')}</select></label><label class="cm-check"><input type="checkbox" name="refreshRefs" value="1">显式更新已选角色/场景到当前版本</label><label class="cm-label">本格角色服装备注<input name="outfit" value="${E(q.outfit)}" placeholder="留空沿用角色固定版本服装"></label></section><section><h3>文字层 · 保存不触发生图</h3><label class="cm-label">对白<textarea name="dialogue" rows="4">${E(b.dialogue)}</textarea></label><label class="cm-label">对白说话人<select name="speakerId"><option value="">未指定</option>${Q.assets(c,'角色').map(a=>`<option value="${a.id}" ${q.text.speakerId===a.id?'selected':''}>${E(a.name)}</option>`).join('')}</select></label><small>说话人须属于本格出场角色；否则保存为未指定。</small><label class="cm-label">旁白<textarea name="narration" rows="3">${E(q.text.narration)}</textarea></label><label class="cm-label">音效字<input name="sfx" value="${E(q.text.sfx)}" placeholder="叮铃 / 沙沙"></label><p>当前 ${adoptedLabel(b)}。保存脚本不自动生成或采用图像。</p></section></div><button class="cm-button primary">保存分格与文字层</button></form>`,B('取消','close'),true);}
  function compare(c,b){const used=Q.adopted(b);S.modal('第'+(c.e.boards.indexOf(b)+1)+'格 · 图像候选比较',`<p>已采用：${used?'v'+used.version:'无'}。左右比较无字底图；当前文字层不进入生图输入。所有画面均为矢量示意。</p><div class="co-candidates">${b.comic.images.map(im=>`<article class="cm-panel"><h3>图像 v${im.version} · ${im.id===b.comic.adoptedId?'已采用':im.status==='failed'?'失败':'待采用'}</h3>${im.status==='ready'?imageHTML(im):`<div class="co-failure">${E(im.error)}</div>`}<p>${E(im.input.action)} · ${E(im.input.shot)}</p><small>角色：${E(im.input.cast.map(r=>rName(r)).join(' / ')||'未指定')}<br>场景：${E(im.input.scene?rName(im.input.scene):'未指定')}<br>服装：${E(im.input.outfit||im.input.cast.map(r=>r.snapshot.outfit).join(' / ')||'待确认')}</small>${B(im.id===b.comic.adoptedId?'✓ 当前采用':'采用此图像','adopt',b.id,`data-image="${im.id}" ${im.status!=='ready'||im.id===b.comic.adoptedId?'disabled':''}`)}</article>`).join('')||'<p>尚无候选。先生成本格示例，再比较采用。</p>'}</div>`,B('关闭比较','close')+B('仅重做本格示例','generate',b.id)+B('模拟本格失败','fail',b.id),true);}
  C.comicAssets=c=>{if(c.c.kind==='episode')return C.originalAssets(c);Q.ensure(c);return `<section class="cm-panel"><h2>角色与场景，先草案后修正。</h2><p>不要求三视图。草案可改名和修正外观；已有分格固定引用原版本，编辑分格时可显式选择当前版本。</p><div class="co-toolbar">${B('建立并联动占位草案','seed')}${B('＋ 新角色草案','new-character')}${B('＋ 新场景草案','new-scene')}${link('返回逐格编辑 →',path(c,'boards','flow'),'cm-button primary')}</div></section><div class="co-assets">${['角色','场景'].flatMap(type=>Q.assets(c,type).map(a=>`<section class="cm-panel"><small>${type} · v${a.version} · ${a.draft?'草案':'参考'}</small><h3>${E(a.name)}</h3><p>${E(a.desc)}</p>${a.outfit?`<p>服装：${E(a.outfit)}</p>`:''}${B('修正为新版本','edit-asset',a.id)}<details><summary>被引用的分格</summary>${c.p.chapters.flatMap(ch=>M.ensure(c.p,ch).boards.filter(b=>b.comic?.cast.some(r=>r.id===a.id)||b.comic?.scene?.id===a.id).map(b=>`<p>${E(ch.title)} / ${E(b.title)} · 引用v${b.comic.cast.find(r=>r.id===a.id)?.version||b.comic.scene?.version}</p>`)).join('')||'<p>尚未引用</p>'}</details></section>`)).join('')}</div>`;};
  function assetForm(c,a,type){S.modal(a?'修正'+a.name+' · 保留旧版本':'新建'+type+'草案',`<form data-comic-form="asset" data-id="${a?.id||''}"><input type="hidden" name="type" value="${a?.type||type}"><label class="cm-label">名称<input name="name" required value="${E(a?.name||'')}"></label><label class="cm-label">外观 / 场景设定<textarea name="desc" rows="4" required>${E(a?.desc||'')}</textarea></label>${(a?.type||type)==='角色'?`<label class="cm-label">默认服装<input name="outfit" value="${E(a?.outfit||'')}"></label>`:''}<p>新版本不会自动替换已有分格引用或已采用图像。</p><button class="cm-button primary">保存资产草案版本</button></form>`,B('取消','close'));}
  C.comicLayout=c=>{Q.ensure(c);return `<div class="cm-stage-toolbar"><div><h2>把画面和文字，排成可独立阅读的漫画。</h2><p>格距只影响排版，不修改图像资产。${c.e.boards.filter(b=>Q.adopted(b)).length}/${c.e.boards.length}格已采用底图。</p></div>${B('导出独立HTML漫画','export','','','cm-button primary')}</div><div class="co-reading-layout"><aside class="cm-panel"><form data-comic-form="layout"><label class="cm-label">条漫格间距（px）<input type="number" min="8" max="96" value="${c.e.comicGap}" name="gap"></label><label class="cm-label">阅读宽度<select name="width"><option value="800" ${c.e.comicWidth===800?'selected':''}>800 px</option><option value="1080" ${c.e.comicWidth===1080?'selected':''}>1080 px</option><option value="480" ${c.e.comicWidth===480?'selected':''}>480 px</option></select></label><button class="cm-button primary">保存排版设置</button></form>${B('打开阅读预览','read')}<p>导出是内嵌底图与文字层的离线HTML文件，非PNG/PDF。所有分格显式采用后可导出。</p>${link('返回逐格编辑',path(c,'boards','flow'),'cm-text-link')}</aside><div class="co-reading" style="max-width:${c.e.comicWidth}px"><header><small>原创矢量示意 · 模拟生成</small><h2>${E(c.p.name)}</h2><p>${E(c.c.title)}</p></header><div class="co-strip" style="gap:${c.e.comicGap}px">${c.e.boards.map((b,i)=>`<figure><small>第${i+1}格 · ${adoptedLabel(b)}</small>${imageHTML(Q.adopted(b)||{art:b.art})}${textHTML(b)}<figcaption>${B('编辑本格','edit',b.id)}${B('图像候选','compare',b.id)}</figcaption></figure>`).join('')}</div><footer>完 · ${c.e.boards.length}格</footer></div></div>`;};
  C.comicReview=c=>`<section class="cm-panel"><h2>独立漫画交付</h2><p>先确认每格的图像采用、说话人和阅读顺序，再导出独立HTML漫画。无音频或视频依赖；底图为矢量示意。</p>${link('检查长条排版与文字',path(c,'comic','flow'),'cm-button ghost')}${B('导出独立HTML漫画','export','','','cm-button primary')}<p>已采用 ${c.e.boards.filter(b=>Q.adopted(b)).length}/${c.e.boards.length} 格。</p><h3>本章漫画交付快照 ${c.e.comicDeliveries?.length||0}</h3>${(c.e.comicDeliveries||[]).map(d=>`<p>${E(d.createdAt)} · ${d.snapshot.panels.length}格 · HTML ${B('重新下载此漫画快照','download-snapshot',d.id)}</p>`).join('')}</section>`;
  function exportData(data,name){const html=renderCimoraComicDocument(data,artURL);S.download(html,name,'text/html;charset=utf-8');return html;}
  function preview(c){const html=renderCimoraComicDocument(Q.document(c),artURL);S.modal('独立阅读预览 · 示意漫画',`<iframe title="漫画阅读预览" sandbox srcdoc="${E(html)}" class="co-reader-frame"></iframe>`,B('关闭阅读','close'),true);}
  document.addEventListener('click',ev=>{
    const download=ev.target.closest('[data-act="download-export"]');if(download){const rec=S.state.exports.find(x=>x.id===download.dataset.id),loc=rec?.comicDelivery;if(loc){ev.preventDefault();ev.stopImmediatePropagation();const cc=M.context(loc.projectId,loc.chapterId),d=cc.e.comicDeliveries?.find(x=>x.id===loc.id);if(d)exportData(d.snapshot,'cimora-comic-'+d.id+'.html');return;}}
    const el=ev.target.closest('[data-comic]'),legacy=ev.target.closest('[data-cm]');if(!el&&!legacy)return;const c=C.ctx();if(!c||c.c.kind==='episode'||c.e.importDraft)return;
    let action=el?.dataset.comic,id=el?.dataset.id;
    if(!el){const a=legacy.dataset.cm;if(a==='edit-board'){action='edit';id=c.e.boards[+legacy.dataset.index]?.id;}else if(a==='comic-export')action='export';else if(a==='seed-assets')action='seed';else if(a==='add-board')action='add';else if(a==='run-plan'||a==='run-node'&&['sketch','final'].includes(legacy.dataset.node))action='batch';else return;}
    ev.preventDefault();ev.stopImmediatePropagation();Q.ensure(c);if(action==='close'){S.close();return;}if(['read','compare','assets','edit','edit-asset','new-character','new-scene','download-snapshot'].includes(action)===false&&!safe(c))return;
    const b=Q.find(c,id);
    switch(action){
      case'assets':S.route(path(c,'assets','flow'));return;
      case'seed':Q.seed(c);paint();S.toast('占位草案已关联，请修正姓名、外观和场景。');return;
      case'edit':if(b)edit(c,b);return;
      case'new-character':assetForm(c,null,'角色');return;
      case'new-scene':assetForm(c,null,'场景');return;
      case'edit-asset':assetForm(c,S.state.assets.find(a=>a.id===id));return;
      case'generate':case'fail':{const r=Q.generate(c,id,{fail:action==='fail'});if(r.error){S.toast(r.error);return;}paint();compare(c,b);return;}
      case'compare':if(b)compare(c,b);return;
      case'adopt':{const error=Q.adopt(c,id,el.dataset.image);if(error)S.toast(error);else{paint();compare(c,b);}return;}
      case'move':{const i=c.e.boards.indexOf(b),j=i+Number(el.dataset.dir);if(j<0||j>=c.e.boards.length)return;[c.e.boards[i],c.e.boards[j]]=[c.e.boards[j],c.e.boards[i]];c.e.reviewChecks=[false,false,false];M.save();paint();return;}
      case'duplicate':{const copy=M.clone(b);copy.id=S.id('panel');copy.title+=' · 副格';delete copy.scriptSource;c.e.boards.splice(c.e.boards.indexOf(b)+1,0,copy);M.save();paint();return;}
      case'add':c.e.boards.push({id:S.id('panel'),title:'新的情节',action:'描述这一格的动作。',dialogue:'',shot:'中景',art:0,version:1,approved:false});Q.ensure(c);M.save();paint();return;
      case'batch':S.modal('为未采用格生成示例候选',`<p>范围：${c.e.boards.filter(b=>!Q.adopted(b)).length}格。已采用格跳过，每格仅保存一个待采用图像候选；不自动采用、不收费。</p>`,B('取消','close')+B('确认生成未采用格候选','confirm-batch'));return;
      case'confirm-batch':for(const b of c.e.boards.filter(b=>!Q.adopted(b)))Q.generate(c,b.id);S.close();paint();return;
      case'read':preview(c);return;
      case'export':{if(!c.e.boards.length||c.e.boards.some(b=>!Q.adopted(b))){S.toast('请先为每格显式采用一个图像候选，再导出漫画。');return;}const d={id:S.id('comic-delivery'),createdAt:new Date().toISOString(),snapshot:Q.document(c)};c.e.comicDeliveries??=[];c.e.comicDeliveries.unshift(d);S.state.exports.unshift({id:d.id,projectId:c.p.id,name:c.p.name+' · '+c.c.title,kind:'HTML漫画',status:'完成',size:c.e.boards.length+'格',date:'刚刚',comicDelivery:{projectId:c.p.id,chapterId:c.c.id,id:d.id}});M.save();exportData(d.snapshot,'cimora-comic-'+c.p.id+'-'+d.id+'.html');return;}
      case'download-snapshot':{const d=c.e.comicDeliveries?.find(x=>x.id===id);if(d)exportData(d.snapshot,'cimora-comic-'+d.id+'.html');return;}
    }
  },true);
  document.addEventListener('submit',ev=>{const f=ev.target.closest('[data-comic-form]');if(!f)return;ev.preventDefault();ev.stopImmediatePropagation();const c=C.ctx();if(!safe(c))return;const v=Object.fromEntries(new FormData(f));let error;if(f.dataset.comicForm==='layout')error=Q.layout(c,v);else if(f.dataset.comicForm==='panel')error=Q.editPanel(c,f.dataset.id,{...v,castIds:new FormData(f).getAll('cast')});else if(f.dataset.id)error=Q.editAsset(c,f.dataset.id,v);else Q.addAsset(c,v);S.navigationSaved?.(f,!error);if(error){S.toast(error);return;}S.close();paint();});
  const oldAfter=C.afterRender;C.afterRender=route=>{oldAfter(route);const id=route.params.get('panel');if(id)S.$('#co-panel-'+id)?.scrollIntoView({block:'center'});};
  C.comicBaseImage=b=>{const image=b.comicSource?.baseImage||Q.adopted(b);return image?imageHTML(image,b.title+' · 固定无字底图'):'';};
  C.comicShotImage=s=>{const image=s.sources?.[0]?.snapshot.comicSource?.baseImage;return image?imageHTML(image,s.title+' · 已引用无字底图'):'';};
  C.comicSourceDetails=b=>{const x=b.comicSource||(b.comic&&Q.source(b));if(!x)return '';const input=x.baseImage?.input;return `<div class="co-source"><p>无字底图：${E(x.baseImage?.id||'未采用')} · 对白归属：${E(x.text.speakerName||'未指定')}</p><small>脚本角色/场景：${E([...x.cast.map(r=>rName(r)),...(x.scene?[rName(x.scene)]:[])].join(' / '))}</small>${input?`<p>图像生成引用：${E([...input.cast.map(r=>rName(r)),...(input.scene?[rName(input.scene)]:[])].join(' / '))} / 服装：${E(input.outfit||input.cast.map(r=>r.snapshot.outfit).join(' / ')||'待确认')}</p>`:''}<p>旁白：${E(x.text.narration||'无')} / 音效字：${E(x.text.sfx||'无')}</p></div>`;};
})();


